# -*- coding: utf-8 -*-
# BIRZHA_09_09_VECHER_V1
"""
Дописывает БИРЖА.md вечером 09.09 и чинит голову, которая врала.

═══ ЧТО ДЕЛАЕТ ═══

  1. Шапка «## Состояние на 06.09» → «## Состояние на 09.09» с
     короткой врезкой: что стоит на сегодня и куда идти дальше.
     Раньше голова документа звала собрать живой кадр и разобрать
     NZDUSD — оба сделаны ещё 08.09.
  2. Раздел «## С чего начинать дальше» переписан целиком: вместо
     протухшего NZDUSD — порядок ключ → рука → история → веса.
  3. В таблицу истории дописана строка «09.09 (вечер)».

Ничего не удаляет, кроме устаревшего «с чего начинать» — прежний
текст оттуда уезжает в историю сессий, не пропадает.

Запускать из корня репозитория:
    python dopisat_birzhu_09_09_vecher.py

Идемпотентен (маркер BIRZHA_09_09_VECHER_V1). Рядом .bak. Есть --suho.
"""
from __future__ import annotations

import sys
from pathlib import Path

MARKER = "BIRZHA_09_09_VECHER_V1"
SUHO = "--suho" in sys.argv
FAYL = Path("БИРЖА.md")

# ── 1. шапка ─────────────────────────────────────────────────────

SHAPKA_OLD = "## Состояние на 06.09\n"

SHAPKA_NEW = """## Состояние на 09.09

> Голова документа до этого дня стояла на 06.09 и звала делать то,
> что уже сделано. Коротко, что верно на сегодня:
>
> · зрение трейдера починено и подтверждено контрольной меткой;
> · кадр тёмный, с приседающими, живой кадр виден Шефу;
> · знания разделены по моменту работы, подача исправлена;
> · задача — «идти с ходом», один этаж, одно место входа;
> · **не построено главное: слово трейдера не сцеплено с делом.**
>   Заявку вылавливают из текста, этаж живёт в трёх местах сразу.
>   Отсюда весь вечер 09.09 и Закон Рычага (см. низ документа).
>
> Куда идти: **ключ → рука на вход → история → веса.**

"""

# ── 2. «с чего начинать» ─────────────────────────────────────────

NACHAT_OLD = "## С чего начинать дальше\n"

NACHAT_NEW = """## С чего начинать дальше

Порядок принят Шефом вечером 09.09. Он не про Биржу одну — это
применение Закона Рычага, внесённого в `ЧЕРТЁЖ_ЕДИНИЦЫ.md`:
**утверждение без рычага — не утверждение.**

**1. КЛЮЧ ЖИТЕЛЯ.** Нажал пузырёк — воткнул ключ, и весь кабинет
развернулся под него: аватар, инструмент, этаж, кадр, стол, дневник,
вахта. «Кто воткнул, того и музыка играет.» Общего выбора в городе
нет вовсе — значит четвёртому инструменту негде завестись. Вахта
тоже при жителе: запоминается, на чьём ключе нажата, трое несут три
вахты, есть она или нет — видно яркой меткой на ключе. Звонок
адресный: сработала вахта Ильи — будят Илью.

**2. РУКА НА ВХОД.** Заявка перестаёт быть текстом. Отдельное
действие: направление, цена, стоп, лот. Позвал — заявка встала и
видна в столе; не позвал — не встала, сколько ни рассказывай. Пока
цифры вылавливает разбор, «сказал и не вошёл» неотличимо от «вошёл».

**3. ИСТОРИЯ.** Дневник пишет то, что случилось, а не то, что житель
про себя подумал. Без руки история — из слов.

**4. ВЕСА.** Последними, потому что раньше нечего считать.

Кадр при этом рисуется ВСЕГДА, как только трейдер сказал «иду» — так
ловим на слове устройством, а не уговорами в бумаге. Текучка не
переписывает рабочий этаж: на следующей побудке картинка сверяется с
вахтовой, не совпала — сброс и показ вахтовой.

### Прежний хвост (06.09, разобран — оставлено как история)

"""

# ── 3. строка истории ────────────────────────────────────────────

ISTORIYA_OLD = "\n<!-- BIRZHA_09_09_V1 -->"

ISTORIYA_NEW = """
| 09.09 (вечер) | **Три раза за вечер трейдера поймали на вранье — и трижды виноватой оказалась постройка.** (1) Сказал «смотрел H4» при кадре H1 — потому что кадров ДВА: Шефу рисуется по его выбору, трейдеру по его рабочему этажу; разбирать ответы трейдера по картинке Шефа нельзя, проверять надо контрольной меткой. (2) Сказал «называю цену» и не вошёл — потому что рычага для входа у него нет, заявку вылавливает из текста код. (3) Забраковал верное место словами «Аллигатор спит, разворотник в спящей пасти неинформативен» — потому что так написано в промпте («спит — флэт, работы нет») и в знаниях. Там же нашлась и причина трёх типов входа: в списке полки осталась строка «входы — три места входа», хотя `VHODY.md` уже переехал в `ведение/`. **Вахта не будила Илью — доказано его же логом:** стояла на H1, звонила по часовой свече, а повод будить считался по паре трейдера (H4); «сейчас 12:00» при новой свече 17:00 — это последний закрытый H4. Этаж H4 никто ему не назначал: в `vybor.py` при невыбранном этаже тихо подставлялся `ETAZH_OT_KOMFORTA`. **Отсюда ЗАКОН РЫЧАГА, внесён в `ЧЕРТЁЖ_ЕДИНИЦЫ.md`:** утверждение без рычага — не утверждение; «сказал, напрягся, сделал». Три следствия: слово без рычага не судится (это наша недоделка, не ложь жителя); один предмет — одно место (если двое помнят об одном, оба скажут правду и разойдутся); рычаг оставляет след — кто, когда и зачем. **Решения Шефа:** выбор и вся картина привязаны к активному пузырьку — ключу жителя, а не к общему выбору города (общий означал бы, что все трое торгуют одну пару — тот самый четвёртый инструмент); трейдер может сам переехать на другой рабочий этаж, но «самовольно и с обоснованием»; защиты от дурака на вахте не ставить — подтверждение закрыло бы жителю дверь. **Адекватность исполнения:** промахнуться можно на трёх разных шагах — не понял (видно сразу), не смог (видно по результату), замысел плох (лечится опытом); мешать их нельзя. Намерение требуется не везде, а по весу дела: посмотреть — не нужно, переставить — причина строкой, потратить — обязательно. **Веса по областям:** вес есть у действия и у жителя, но у жителя в конкретной области, и сравниваются только соотносимые; один и тот же может быть мастером в одном и дрыщом в другом. Область — не глагол и не имя рычага, а **то, в чём житель хорош по результату**; рычаг лишь доказывает, что действие было. Успех — не факт, а результат, проверенный временем; на Бирже вес растёт от прибыли и успешных входов, и то и другое считается по времени. **Редкость — итог, а не украшение** (разбор Софии, принят): Mythic возникает, а не назначается; все жители сброшены в `Common`, места остались `Mythic`; Хранитель — не «волшебная особа», а тот, кто хранит. **Первый уровень пути переписан у городского Брата: не «покажи, что ты крут», а ВЫЖИВИ** — крутое на первом уровне это уцелеть, промолчать и уйти считается таким же ходом. Собрано и отдано файлами: строка про три входа из промптов; лекарь флэта (снимает неверную первую версию — Брат написал «в конце хода пасть закрыта», Шеф отменил: «Аллигатор не так показывает конец хода»); кадр без общего склада matplotlib (вероятная причина обрывов связи, воспроизвести не удалось); пара разворотник+приседающий в знания (нигде не было сказано, что они значат ВМЕСТЕ — один бар с двух сторон, совпали = сильнее) и лазейка «подожду ясности» закрыта по смыслу, а не по фразе |

<!-- BIRZHA_09_09_V1 -->"""


def nayti_koren() -> Path:
    kandidat = Path(__file__).resolve().parent
    for papka in [kandidat, *kandidat.parents]:
        if (papka / FAYL).is_file():
            return papka
    print("Не нашёл БИРЖА.md рядом со скриптом.")
    print("Положи скрипт в корень репозитория и запусти оттуда.")
    input("Enter — закрыть...")
    sys.exit(1)


def main() -> None:
    koren = nayti_koren()
    p = koren / FAYL
    tekst = p.read_text(encoding="utf-8")
    print(f"Файл: {p}  ({len(tekst)} симв.)")

    if MARKER in tekst:
        print("уже дописано — маркер на месте")
        input("Enter — закрыть...")
        return

    pravki = [("шапка документа", SHAPKA_OLD, SHAPKA_NEW),
              ("с чего начинать дальше", NACHAT_OLD, NACHAT_NEW),
              ("строка истории 09.09 вечер", ISTORIYA_OLD, ISTORIYA_NEW)]

    for kak, staroe, _ in pravki:
        n = tekst.count(staroe)
        if n != 1:
            print(f"⚠ «{kak}»: совпадений {n}, нужно 1 — НИЧЕГО не трогаю")
            input("Enter — закрыть...")
            return

    novyy = tekst
    for kak, staroe, novoe in pravki:
        novyy = novyy.replace(staroe, novoe, 1)
        print(f"  ✔ {kak}")

    novyy = novyy.rstrip("\n") + f"\n\n<!-- {MARKER} -->\n"

    if SUHO:
        print("\n(сухой прогон — ничего не записано)")
        input("Enter — закрыть...")
        return

    bak = p.with_suffix(p.suffix + ".bak_09_09_vecher")
    if not bak.exists():
        bak.write_text(tekst, encoding="utf-8")
    p.write_text(novyy, encoding="utf-8")

    print(f"\n✔ готово ({len(novyy)} симв.). Бэкап: {bak.name}")
    input("\nEnter — закрыть...")


if __name__ == "__main__":
    main()
